// Test-count drift gate.
//
// README's **Total** row advertises a precise test count + Jest/Playwright
// subcounts (generated by scripts/generate-test-table.mjs but never gated). This
// validates them against the LIVE suite:
//   - Jest:       numTotalTests from the jest --json results CI writes
//   - Playwright: `npx playwright test --list` Total (no browsers needed)
//
// CI runs this right after the coverage step (which now also emits
// jest-results.json). Locally without that file it SKIPS (exit 0).
import { existsSync, readFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const jestPath = join(root, "jest-results.json");

if (!existsSync(jestPath)) {
  console.log(
    "check-test-count: skipped — no jest-results.json. " +
      "Run `npm run test:all -- --json --outputFile=jest-results.json` first (CI does).",
  );
  process.exit(0);
}

const jest = JSON.parse(readFileSync(jestPath, "utf8")).numTotalTests;

const pw = spawnSync("npx", ["playwright", "test", "--list"], { cwd: root, encoding: "utf8" });
const pwMatch = (pw.stdout || "").match(/^Total: (\d+) tests? in/m);
if (!pwMatch) {
  console.error(
    `check-test-count: could not read the Playwright total from --list:\n${pw.stderr || pw.stdout}`,
  );
  process.exit(1);
}
const playwright = Number(pwMatch[1]);
const total = jest + playwright;

const readme = readFileSync(join(root, "README.md"), "utf8");
const m = readme.match(/\*\*(\d+)\*\* \((\d+) Jest \+ (\d+) Playwright\)/);
if (!m) {
  console.error(
    "check-test-count: could not find the **Total** (N Jest + M Playwright) row in README.md.",
  );
  process.exit(1);
}
const rTotal = Number(m[1]);
const rJest = Number(m[2]);
const rPw = Number(m[3]);

const drift = [];
if (rJest !== jest) drift.push(`  Jest: README ${rJest}, actual ${jest}`);
if (rPw !== playwright) drift.push(`  Playwright: README ${rPw}, actual ${playwright}`);
if (rTotal !== total) drift.push(`  Total: README ${rTotal}, actual ${total}`);

if (drift.length) {
  console.error(
    `check-test-count: README test counts are stale:\n${drift.join("\n")}\n\n` +
      "Run `npm run readme:test-table` to regenerate the table.",
  );
  process.exit(1);
}

console.log(
  `check-test-count: OK — README ${total} (${jest} Jest + ${playwright} Playwright) matches the live suite.`,
);
